const sourceSlug=(value:string)=>value.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
export const speciesCatalog: SpeciesProfile[] = rawSpeciesCatalog.map(profile=>{
  if(profile.sourceUrl&&profile.verifiedAt)return profile;
  if(profile.category==="fish"&&!profile.scientificName.includes("sp.")&&!profile.scientificName.toLowerCase().includes("hybrid"))return {...profile,sourceUrl:`https://www.fishbase.se/summary/${profile.scientificName.replace(/\s+/g,"-")}.html`,verifiedAt:"2026-08-17"};
  if(profile.category==="shrimp"||profile.category==="snail")return {...profile,sourceUrl:`https://www.seriouslyfish.com/species/${sourceSlug(profile.scientificName)}/`,verifiedAt:"2026-08-17"};
  return profile;
});

// Bütünlük denetimi geliştirmede, testlerde ve CI'da (`pnpm verify`) çalışır; üretim derlemesinde kullanıcının tarayıcısında çalışmaz (docs/DECISIONS/0015-katalog-modulleri-ve-sayfa-hizi.md).
function assertSpeciesCatalogIntegrity(){
  assertUniqueIds("Canlı",speciesCatalog);
  const unverifiedSpeciesIds:string[]=[];
  for(const item of speciesCatalog){
    if(item.adultSizeCm<=0||item.minVolumeL<=0||(item.category==="fish"&&!item.minTankLengthCm&&!item.tankLengthDataNote)||(item.minTankLengthCm!==undefined&&item.minTankLengthCm<=0)||item.minGroup<=0||item.wasteFactor<=0)throw new Error(`Geçersiz canlı sayısal değeri: ${item.id}`);
    if(item.minTankLengthCm&&item.tankLengthDataNote)throw new Error(`Canlı profilinde gereksiz tank uzunluğu veri notu: ${item.id}`);
    if(item.temperature[0]>=item.temperature[1]||item.ph[0]>=item.ph[1])throw new Error(`Geçersiz canlı aralığı: ${item.id}`);
    if(item.waterTypes?.length===0||item.waterTypes?.some(type=>!["freshwater","saltwater","brackish"].includes(type)))throw new Error(`Geçersiz canlı su türü: ${item.id}`);
    if(item.specificGravity&&(item.specificGravity[0]>=item.specificGravity[1]||item.specificGravity[0]<1||item.specificGravity[1]>1.04))throw new Error(`Geçersiz canlı özgül ağırlık aralığı: ${item.id}`);
    if(Boolean(item.sourceUrl)!==Boolean(item.verifiedAt))throw new Error(`Eksik canlı kaynak/tarih çifti: ${item.id}`);
    if(!item.sourceUrl||!item.verifiedAt)unverifiedSpeciesIds.push(item.id);
  }
  if(unverifiedSpeciesIds.length)throw new Error(`Doğrulanmamış canlı kayıtları: ${unverifiedSpeciesIds.join(", ")}`);
}
if(process.env.NODE_ENV!=="production")assertSpeciesCatalogIntegrity();

// Arama dizini (docs/DECISIONS/0015-katalog-modulleri-ve-sayfa-hizi.md): `normalize` Türkçe yerel ayarla küçük harfe çevirdiği için
// yavaştır ve eski doğrusal aramalar her çağrıda yüzlerce kaydı yeniden biçimlendiriyordu. Katalog çalışma sırasında değişmez;
// biçimlendirilmiş adlar ilk kullanımda bir kez hesaplanır. Sonuçlar eski aramalarla birebir aynıdır: eşleşme varsa katalog
// sırasındaki ilk kayıt döner. Kimlik dizini biçimlendirme gerektirmediği için ayrı tutulur; ad dizini yalnızca kimliği
// olmayan bir kayıt ya da katalog araması geldiğinde kurulur.
let speciesByIdCache: Map<string, SpeciesProfile> | undefined;
function speciesByIdIndex() {
  if (speciesByIdCache) return speciesByIdCache;
  speciesByIdCache = new Map();
  for (const profile of speciesCatalog) if (!speciesByIdCache.has(profile.id)) speciesByIdCache.set(profile.id, profile);
  return speciesByIdCache;
}
interface SpeciesLookup { scientific: Map<string, number>; names: Map<string, number>; searchNames: string[][] }
let speciesLookupCache: SpeciesLookup | undefined;
function rememberFirst(map: Map<string, number>, key: string, index: number) { if (!map.has(key)) map.set(key, index); }
function speciesLookup(): SpeciesLookup {
  if (speciesLookupCache) return speciesLookupCache;
  const scientific = new Map<string, number>(), names = new Map<string, number>();
  const searchNames = speciesCatalog.map((profile, index) => {
    const commonName = normalize(profile.commonName) ?? "", scientificName = normalize(profile.scientificName) ?? "", aliases = (profile.aliases ?? []).map((alias) => normalize(alias) ?? "");
    rememberFirst(scientific, scientificName, index);
    rememberFirst(names, commonName, index);
    for (const alias of aliases) rememberFirst(names, alias, index);
    return [commonName, scientificName, ...aliases];
  });
  speciesLookupCache = { scientific, names, searchNames };
  return speciesLookupCache;
}
export const speciesById = (id?: string) => id === undefined ? undefined : speciesByIdIndex().get(id);
// Ad dizini katalog parçalarına da yazılır (src/data/catalog-bucket-builders.ts); tarayıcıdaki yükleyici böylece aynı eşlemeyi kullanır.
export function speciesNameIndex(): { scientific: ReadonlyMap<string, number>; names: ReadonlyMap<string, number> } {
  const { scientific, names } = speciesLookup();
  return { scientific, names };
}
// Doğrulanmış kayıt kuralı veri içermeyen ortak modülde (tarayıcıdaki parça yükleyici de kullanır).
export { isVerifiedSpeciesProfile };
export const speciesWaterTypes = (profile:SpeciesProfile): AquariumType[] => profile.waterTypes ?? ["freshwater"];
export const speciesGroupLabels: Record<NonNullable<SpeciesProfile["group"]>,string> = {livebearer:"Canlı doğuranlar",tetra:"Tetralar",rasbora:"Rasboralar",danio:"Daniolar",barb:"Barblar",rainbowfish:"Gökkuşağı balıkları",killifish:"Killifishler",cichlid:"Cichlidler",labyrinth:"Labirentliler",bottom:"Dip balıkları ve vatozlar",goby:"Goby ve kaya balıkları",puffer:"Puffer / balon balıkları",monster:"Monster / büyük türler",coldwater:"Soğuk su balıkları",shrimp:"Karidesler",snail:"Salyangozlar",crayfish:"Kerevitler",other:"Diğer canlılar"};
export const speciesGroup = (item: SpeciesProfile): NonNullable<SpeciesProfile["group"]> => item.group ?? (item.category==="shrimp"?"shrimp":item.category==="snail"?"snail":item.id.includes("tetra")?"tetra":item.id==="guppy"?"livebearer":item.id==="betta"?"labyrinth":["ancistrus","corydoras-panda"].includes(item.id)?"bottom":item.id==="goldfish"?"coldwater":"other");
export const speciesForCategoryAndWaterType = (category: Livestock["category"], waterType: AquariumType) => speciesCatalog.filter(item=>item.category===category&&speciesWaterTypes(item).includes(waterType));
export const speciesGroupsForCategoryAndWaterType = (category: Livestock["category"], waterType: AquariumType) => [...new Set(speciesForCategoryAndWaterType(category,waterType).map(speciesGroup))];
export const speciesForCatalogSearch = (value: string, category: Livestock["category"], waterType: AquariumType) => {
  const query = normalize(value);
  if (!query) return undefined;
  const { searchNames } = speciesLookup();
  return speciesForCatalogExactSearch(value, category, waterType) ?? speciesCatalog.find((profile, index) => profile.category === category && speciesWaterTypes(profile).includes(waterType) && searchNames[index].some((name) => name.includes(query)));
};
export const speciesForCatalogExactSearch = (value: string, category: Livestock["category"], waterType: AquariumType) => {
  const query = normalize(value);
  if (!query) return undefined;
  const { searchNames } = speciesLookup();
  return speciesCatalog.find((profile, index) => profile.category === category && speciesWaterTypes(profile).includes(waterType) && searchNames[index].includes(query));
};
// Katalog kimliği yoksa eski kayıtlar bilimsel ada ya da ortak ada/eş ada göre eşlenir; birden fazla eşleşmede katalogda önce gelen kazanır.
export const speciesForLivestock = (item: Livestock) => {
  const profile = speciesById(item.catalogId);
  if (profile) return profile;
  const { scientific, names } = speciesLookup();
  const scientificName = normalize(item.scientificName), commonName = normalize(item.commonName);
  const matches = [scientificName === undefined ? undefined : scientific.get(scientificName), commonName === undefined ? undefined : names.get(commonName)].filter((index): index is number => index !== undefined);
  return matches.length ? speciesCatalog[Math.min(...matches)] : undefined;
};
